"""Evaluate the small spreadsheet language described in README.md."""

import re


_NUMBER_RE = re.compile(r"(?:\d+(?:\.\d*)?|\.\d+)")
_CELL_RE = re.compile(r"[A-Za-z]+\d*")
_BARE_NUMBER_RE = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)")


class CycleError(Exception):
    """Raised when cell references contain a dependency cycle."""


class _FormulaParser:
    def __init__(self, formula, resolve):
        self.formula = formula
        self.resolve = resolve
        self.position = 0

    def parse(self):
        value = self._expression()
        self._skip_whitespace()
        if self.position != len(self.formula):
            self._error("unexpected token")
        return value

    def _expression(self):
        value = self._term()
        while True:
            operator = self._take_one_of("+-")
            if operator is None:
                return value
            operand = self._term()
            if operator == "+":
                value += operand
            else:
                value -= operand

    def _term(self):
        value = self._unary()
        while True:
            operator = self._take_one_of("*/")
            if operator is None:
                return value
            operand = self._unary()
            if operator == "*":
                value *= operand
            else:
                value /= operand

    def _unary(self):
        self._skip_whitespace()
        if self._take("-"):
            return -self._unary()
        return self._primary()

    def _primary(self):
        self._skip_whitespace()

        if self._take("("):
            value = self._expression()
            if not self._take(")"):
                self._error("expected ')'")
            return value

        number = _NUMBER_RE.match(self.formula, self.position)
        if number is not None:
            self.position = number.end()
            return float(number.group())

        reference = _CELL_RE.match(self.formula, self.position)
        if reference is not None:
            self.position = reference.end()
            return self.resolve(reference.group())

        self._error("expected a number, cell reference, or '('")

    def _take_one_of(self, characters):
        self._skip_whitespace()
        if (
            self.position < len(self.formula)
            and self.formula[self.position] in characters
        ):
            character = self.formula[self.position]
            self.position += 1
            return character
        return None

    def _take(self, character):
        self._skip_whitespace()
        if (
            self.position < len(self.formula)
            and self.formula[self.position] == character
        ):
            self.position += 1
            return True
        return False

    def _skip_whitespace(self):
        while (
            self.position < len(self.formula)
            and self.formula[self.position].isspace()
        ):
            self.position += 1

    def _error(self, message):
        raise ValueError(
            f"{message} at position {self.position} in formula {self.formula!r}"
        )


def evaluate(cells):
    """Return the computed floating-point value of every cell in *cells*."""
    values = {}
    visiting = set()
    stack = []

    def resolve(name):
        if name in values:
            return values[name]
        if name in visiting:
            cycle_start = stack.index(name)
            cycle = stack[cycle_start:] + [name]
            raise CycleError("dependency cycle: " + " -> ".join(cycle))

        raw_value = cells[name]
        visiting.add(name)
        stack.append(name)
        try:
            if raw_value.startswith("="):
                value = _FormulaParser(raw_value[1:], resolve).parse()
            else:
                number = raw_value.strip()
                if _BARE_NUMBER_RE.fullmatch(number) is None:
                    raise ValueError(f"invalid bare number in cell {name!r}: {raw_value!r}")
                value = float(number)
            values[name] = value
            return value
        finally:
            stack.pop()
            visiting.remove(name)

    for cell_name in cells:
        resolve(cell_name)

    return values

