cases = [
    ({"A": "=3/2"}, {"A": 1.5}),
    ({"A": "=1-2-3"}, {"A": -4.0}),
    ({"A": "=8/4/2"}, {"A": 1.0}),
    ({"A": " = ignored"}, None),
    ({"A": "=-(B + 1)", "B": "3.5"}, {"A": -4.5, "B": 3.5}),
    ({"A": "=--3"}, {"A": 3.0}),
    ({"A": " =5"}, None),
]
for cells, expected in cases:
    try:
        result = evaluate(cells)
        print(cells, result)
        if expected is not None:
            assert result == expected
    except Exception as exc:
        print(cells, type(exc).__name__, exc)

for cells in ({"A": "=A"}, {"A": "=B", "B": "=C", "C": "=A"}):
    try:
        evaluate(cells)
    except CycleError as exc:
        print(type(exc).__name__, exc)
    else:
        raise AssertionError("expected CycleError")
